import React, { useState, useEffect } from 'react';
import { useLocation, Link } from 'react-router-dom';
import './SuccessPage.css';

const SuccessPage = () => {
  const location = useLocation();
  const { formData } = location.state || {};
  const [showContent, setShowContent] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => {
      setShowContent(true);
    }, 500);
    return () => clearTimeout(timer);
  }, []);

  if (!formData) {
    return (
      <div className="success-container error">
        <div className="error-content">
          <span className="error-icon">⚠️</span>
          <h2>Oops! Something went wrong</h2>
          <p>We couldn't find your registration data. Please try registering again.</p>
          <Link to="/" className="back-link error">
            <span>←</span> Return to Registration
          </Link>
        </div>
      </div>
    );
  }

  const sections = [
    {
      title: 'Personal Details',
      icon: '👤',
      data: [
        { label: 'First Name', value: formData.firstName },
        { label: 'Last Name', value: formData.lastName },
        { label: 'Username', value: formData.username }
      ]
    },
    {
      title: 'Contact Information',
      icon: '📱',
      data: [
        { label: 'Email', value: formData.email },
        { label: 'Phone', value: `${formData.countryCode} ${formData.phoneNumber}` }
      ]
    },
    {
      title: 'Location',
      icon: '📍',
      data: [
        { label: 'Country', value: formData.country },
        { label: 'City', value: formData.city }
      ]
    },
    {
      title: 'Identity Details',
      icon: '🆔',
      data: [
        { label: 'PAN Number', value: formData.panNumber },
        { label: 'Aadhar Number', value: formData.aadharNumber }
      ]
    }
  ];

  return (
    <div className={`success-container ${showContent ? 'show' : ''}`}>
      <div className="success-header">
        <div className="success-icon">✨</div>
        <h1>Welcome Aboard!</h1>
        <p className="success-message">
          Your registration has been successfully completed. Here's a summary of your information:
        </p>
      </div>

      <div className="success-grid">
        {sections.map((section, index) => (
          <div 
            key={section.title} 
            className="success-card"
            style={{ animationDelay: `${index * 0.2}s` }}
          >
            <div className="card-header">
              <span className="section-icon">{section.icon}</span>
              <h2>{section.title}</h2>
            </div>
            <div className="card-content">
              {section.data.map(item => (
                <div key={item.label} className="data-row">
                  <span className="data-label">{item.label}:</span>
                  <span className="data-value">{item.value}</span>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      <div className="success-footer">
        <p>Thank you for choosing our service!</p>
        <Link to="/" className="back-link">
          <span>←</span> Return to Registration
        </Link>
      </div>
    </div>
  );
};

export default SuccessPage;
